extern "C" __global__ void tcg_probe(float* out, const float* a, const float* b) {
  extern __shared__ __align__(1024) char smem[];
  const int A_smem = (int)__cvta_generic_to_shared(smem);
  const int B_smem = A_smem + 64*8*4;            // tf32: 4 bytes
  #pragma nv_diag_suppress static_var_with_dynamic_init
  __shared__ unsigned long long mbar[1];
  __shared__ int tmem_addr[1];
  const int mbar_addr = (int)__cvta_generic_to_shared(mbar);
  const int tid = threadIdx.x;
  const int warp_id = tid >> 5;

  // seed smem so the compiler can't elide
  for (int i = tid; i < 64*8; i += blockDim.x) ((float*)smem)[i] = a[i];
  for (int i = tid; i < 8*8;  i += blockDim.x) ((float*)(smem + 64*8*4))[i] = b[i];

  if (warp_id == 0) {
    asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" :: "r"(mbar_addr), "r"(1));
