        s = log.decode(errors="replace").strip()
        if s: print("[NVRTC]", s)
    assert err == nvrtc.nvrtcResult.NVRTC_SUCCESS, f"compile failed {err}"
    sz = nvrtc.nvrtcGetCUBINSize(prog)[1]
    cubin = bytearray(sz); nvrtc.nvrtcGetCUBIN(prog, cubin)
    m = cd.cuModuleLoadData(bytes(cubin))[1]
    f = cd.cuModuleGetFunction(m, b"w_tcgen05")[1]
    maxsmem = cd.cuDeviceGetAttribute(cd.CUdevice_attribute.CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN, d)[1]
    cd.cuFuncSetAttribute(f, cd.CUfunction_attribute.CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, maxsmem)
    return f

FUNC = build()
BN = 256   # N-tile width (mult of 16 for M=128, mult of 8 for M=64); 256 max
NTH = 128  # threads (4 warps)

def run_tcgen05(V, At, BN=BN):
    Bb, _, PHl = V.shape
    NCl = At.shape[2]
    W = torch.zeros(Bb, 32, NCl, device=dev, dtype=torch.float32)
    smem = (64*8 + BN*8) * 4
    grid_n = (NCl + BN - 1) // BN
    a = [np.array([V.data_ptr()], dtype=np.uint64), np.array([At.data_ptr()], dtype=np.uint64),
         np.array([W.data_ptr()], dtype=np.uint64),
         np.array([Bb], dtype=np.int32), np.array([PHl], dtype=np.int32),
         np.array([NCl], dtype=np.int32), np.array([BN], dtype=np.int32)]
