"""KILL-GATE microbench (brief-26): tcgen05 async-MMA W-reduction tile vs the
current Triton _trailing_fused_kernel W-reduction tile, for the n=512 trailing.

Tests the brief's core thesis: does Blackwell 5th-gen async tcgen05.mma (issue
decoupled from completion via mbarrier) beat the Triton tl.dot chain on the
latency-bound W = V^T @ A_trail reduction (M=32 reflectors, K=pheight, N=ncols)?

Computes ONLY W = V^T @ A_trail (the dominant, latency-bound sweep-1 of the
trailing). Both paths are validated against a torch reference, then timed A/B at
util=0, interleaved. Diagnostic only; not a submission. Run wrapped in
`autocuda run exclusive`.
"""
import os, sys
import numpy as np
import torch
import triton
import triton.language as tl
from cuda.bindings import nvrtc, driver as cd

torch.cuda.init(); _ = torch.zeros(1, device="cuda"); torch.cuda.synchronize()
dev = torch.device("cuda")

# ----- problem shape: n=512 j=0 outer block (the dominant trailing) -----
B   = 640
PH  = 512          # pheight
NB  = 32           # reflectors (BLK)
NC  = 480          # ncols (= 512 - 32)
torch.manual_seed(0)
# V stored as Vbuf[b] = (NB=32, PH) -- k slow, pheight contiguous (== V^T already)
V = torch.randn(B, NB, PH, device=dev, dtype=torch.float32) * 0.1
# A_trail stored as (PH, NC) row-major (pheight slow, ncols contiguous)
At = torch.randn(B, PH, NC, device=dev, dtype=torch.float32)

# reference W = V @ At  (V is (32,PH), At is (PH,NC)) -> (32, NC), fp32 (tf32 tol)
W_ref = torch.bmm(V, At)   # (B,32,NC)

# ============================================================================
# tcgen05 W-reduction kernel (NVRTC, sm_100a). One CTA per (matrix, N-tile).
# A operand = V padded to M=64 (rows 32..63 zero); B operand = A_trail tile.
# Accumulate over K=PH in atoms of 8 (TF32) into one TMEM (64 x BN) accumulator.
# ============================================================================
TCG_SRC = r'''
#define MMA_M 64
#define KATOM 8
extern "C" __global__ void w_tcgen05(
    const float* __restrict__ Vb,    // (B, 32, PH)  V^T, k-slow
    const float* __restrict__ Ab,    // (B, PH, NC)  A_trail, row-major
    float* __restrict__ Wb,          // (B, 32, NC)  output W
    int B, int PH, int NC, int BN)   // BN = N-tile width (<=256, mult of 8)
{
  const int bid_mat = blockIdx.y;
  const int n0 = blockIdx.x * BN;
  if (bid_mat >= B) return;
  const int tid = threadIdx.x;
  const int warp_id = tid >> 5;
  const int lane = tid & 31;

  // smem: A-tile (MMA_M x KATOM) + B-tile (BN x KATOM), tf32 (4B), double? no, single.
  extern __shared__ __align__(1024) char smem[];
  float* As = (float*)smem;                       // MMA_M*KATOM floats
  float* Bs = As + MMA_M*KATOM;                   // BN*KATOM floats
  const int As_addr = (int)__cvta_generic_to_shared(As);
  const int Bs_addr = (int)__cvta_generic_to_shared(Bs);

  #pragma nv_diag_suppress static_var_with_dynamic_init
  __shared__ unsigned long long mbar[1];
  __shared__ int tmem_addr[1];
  const int mbar_addr = (int)__cvta_generic_to_shared(mbar);

  if (warp_id == 0) {
    asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" :: "r"(mbar_addr), "r"(1));
    asm volatile("fence.mbarrier_init.release.cluster;");
  } else if (warp_id == 1) {
    const int a = (int)__cvta_generic_to_shared(tmem_addr);
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" :: "r"(a), "r"(BN));
  }
  __syncthreads();
  const int taddr = tmem_addr[0];
  int phase = 0;

  // i_desc TF32: cfmt=F32(1<<4), a=TF32(2<<7), b=TF32(2<<10), N=BN(>>3<<17), M=64(>>4<<24)
  const unsigned i_desc = (1u<<4) | (2u<<7) | (2u<<10) | (((unsigned)BN>>3)<<17) | (((unsigned)MMA_M>>4)<<24);
  auto enc = [](unsigned long long x) -> unsigned long long { return (x & 0x3FFFFull) >> 4ull; };
  // no-swizzle descriptor. Smem holds one (M, KATOM) block contiguous: row-major
  // [m][k], so leading (M) stride = KATOM*4 bytes; the K-atom is the whole tile so
  // SBO is the within-core-matrix stride. Mirror matmul_v1 (BF16) scaled to 4B.
  auto desc = [&](int addr, int height) -> unsigned long long {
    unsigned long long LBO = (unsigned long long)height * 16ull;
    unsigned long long SBO = 8ull * 16ull;
    return enc((unsigned long long)addr) | (enc(LBO) << 16ull) | (enc(SBO) << 32ull) | (1ull << 46ull);
  };

  const float* Vmat = Vb + (long)bid_mat * 32 * PH;     // (32, PH)
  const float* Amat = Ab + (long)bid_mat * PH * NC;     // (PH, NC)

  const int nk = PH / KATOM;   // PH multiple of 8 (512)
  for (int ki = 0; ki < nk; ki++) {
    const int k0 = ki * KATOM;
    // load A-operand tile = V[:, k0:k0+8] padded to M=64. smem layout [m][k].
    // V is (32,PH): V[m][k0+kk]. rows 32..63 -> 0.
    for (int idx = tid; idx < MMA_M*KATOM; idx += blockDim.x) {
      int m = idx / KATOM, kk = idx % KATOM;
      As[idx] = (m < 32) ? Vmat[(long)m*PH + (k0+kk)] : 0.0f;
    }
    // load B-operand tile = A_trail[k0:k0+8, n0:n0+BN]. smem layout [n][k] (B is K x N,
    // tcgen05 wants operand laid contiguous as (N, KATOM) blocks -> [n][k]).
    for (int idx = tid; idx < BN*KATOM; idx += blockDim.x) {
      int nn = idx / KATOM, kk = idx % KATOM;
      int col = n0 + nn;
      Bs[idx] = (col < NC) ? Amat[(long)(k0+kk)*NC + col] : 0.0f;
    }
    __syncthreads();
    asm volatile("tcgen05.fence::after_thread_sync;");
    if (warp_id == 0) {
      unsigned long long ad = desc(As_addr, MMA_M);
      unsigned long long bd = desc(Bs_addr, BN);
      asm volatile(
        "{\n\t.reg .pred p;\n\tsetp.ne.b32 p, %4, 0;\n\t"
        "tcgen05.mma.cta_group::1.kind::tf32 [%0], %1, %2, %3, p;\n\t}"
        :: "r"(taddr), "l"(ad), "l"(bd), "r"(i_desc), "r"(ki));  // ki!=0 -> accumulate
      asm volatile("tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];" :: "r"(mbar_addr) : "memory");
    }
    mbarrier_wait_label:
    asm volatile(
      "{\n\t.reg .pred P1;\n\tWAIT_%=:\n\t"
      "mbarrier.try_wait.parity.acquire.cta.shared::cta.b64 P1, [%0], %1, %2;\n\t"
      "@P1 bra.uni DONE_%=;\n\tbra.uni WAIT_%=;\n\tDONE_%=:\n\t}"
      :: "r"(mbar_addr), "r"(phase), "r"(0x989680));
    phase ^= 1;
    __syncthreads();
  }

  // read W from TMEM. Accumulator is (M=64 rows, BN cols). We only need rows 0..31.
  asm volatile("tcgen05.fence::after_thread_sync;");
  // tcgen05.ld 32x32b.x8 -> each warp's 32 lanes read 32 rows x 8 cols. warp_id*32 = row base.
  float* Wmat = Wb + (long)bid_mat * 32 * NC;
  if (warp_id == 0) {  // rows 0..31 = the 32 real reflectors
    for (int n = 0; n < BN; n += 8) {
      float tmp[8];
      const int addr = taddr + ((warp_id*32)<<16) + n;
      asm volatile("tcgen05.ld.sync.aligned.32x32b.x8.b32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
          : "=f"(tmp[0]),"=f"(tmp[1]),"=f"(tmp[2]),"=f"(tmp[3]),"=f"(tmp[4]),"=f"(tmp[5]),"=f"(tmp[6]),"=f"(tmp[7])
          : "r"(addr));
      asm volatile("tcgen05.wait::ld.sync.aligned;");
      // lane = row (0..31). 8 cols n..n+7. store W[lane][n0+n+c].
      int row = lane;
      for (int c = 0; c < 8; c++) {
        int col = n0 + n + c;
        if (col < NC) Wmat[(long)row*NC + col] = tmp[c];
      }
    }
  }
  __syncthreads();
  if (warp_id == 0)
    asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" :: "r"(taddr), "r"(BN));
