decoupled from completion via mbarrier) beat the Triton tl.dot chain on the
latency-bound W = V^T @ A_trail reduction (M=32 reflectors, K=pheight, N=ncols)?

Computes ONLY W = V^T @ A_trail (the dominant, latency-bound sweep-1 of the
trailing). tcgen05 path is validated against torch reference FIRST (single run);
only if correct does it time A/B vs Triton at util=0, interleaved. Diagnostic
only; not a submission. Run wrapped in `autocuda run exclusive`.

MODE (argv[1]): "validate" (single correctness run, default) or "bench".
"""
import os, sys
import numpy as np
import torch
import triton
import triton.language as tl
from cuda.bindings import nvrtc, driver as cd

MODE = sys.argv[1] if len(sys.argv) > 1 else "validate"
torch.cuda.init(); _ = torch.zeros(1, device="cuda"); torch.cuda.synchronize()
dev = torch.device("cuda")

# ----- problem shape: n=512 j=0 outer block (the dominant trailing) -----
B   = 640
PH  = 512          # pheight
NB  = 32           # reflectors (BLK)
NC  = 480          # ncols (= 512 - 32)
torch.manual_seed(0)
# V stored as Vbuf[b] = (NB=32, PH) -- k slow, pheight contiguous (== V^T already)
V = torch.randn(B, NB, PH, device=dev, dtype=torch.float32) * 0.1
# A_trail stored as (PH, NC) row-major (pheight slow, ncols contiguous)
At = torch.randn(B, PH, NC, device=dev, dtype=torch.float32)
W_ref = torch.bmm(V, At)   # (B,32,NC) reference, fp32 (compare at tf32 tol)

# ============================================================================
# tcgen05 W-reduction kernel (NVRTC, sm_100a). Mirrors gau-nernst matmul_v1
# (no-swizzle, elect_sync-guarded single-thread tcgen05 ops). One CTA per
# (matrix, N-tile). A operand = V padded to M=64; B operand = A_trail tile.
# Accumulate over K=PH in atoms of KATOM=8 (TF32) into one TMEM (64 x BN) acc.
# ============================================================================
TCG_SRC = r'''
constexpr int WARP_SIZE = 32;
constexpr int MMA_M = 64;
constexpr int KATOM = 8;

__device__ inline unsigned elect_one() {
  unsigned pred = 0;
  asm volatile("{\n\t.reg .pred %%px;\n\telect.sync _|%%px, %1;\n\t"
               "@%%px mov.s32 %0, 1;\n\t}" : "+r"(pred) : "r"(0xFFFFFFFF));
  return pred;
}
__device__ inline void mbar_init(int a, int c) {
  asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" :: "r"(a), "r"(c));
}
__device__ inline void mbar_wait(int a, int phase) {
  asm volatile("{\n\t.reg .pred P1;\n\tLAB_WAIT:\n\t"
    "mbarrier.try_wait.parity.acquire.cta.shared::cta.b64 P1, [%0], %1, %2;\n\t"
    "@P1 bra.uni LAB_DONE;\n\tbra.uni LAB_WAIT;\n\tLAB_DONE:\n\t}"
    :: "r"(a), "r"(phase), "r"(0x989680));
}
__device__ inline unsigned long long enc(unsigned long long x){ return (x & 0x3FFFFull) >> 4ull; }

extern "C" __global__ void w_tcgen05(
    const float* __restrict__ Vb,    // (B, 32, PH)
    const float* __restrict__ Ab,    // (B, PH, NC)
    float* __restrict__ Wb,          // (B, 32, NC)
    int B, int PH, int NC, int BN)
{
  const int bid_mat = blockIdx.y;
  const int n0 = blockIdx.x * BN;
  if (bid_mat >= B) return;
  const int tid = threadIdx.x;
  const int warp_id = tid / WARP_SIZE;
  const int lane = tid % WARP_SIZE;

  extern __shared__ __align__(1024) char smem[];
  float* As = (float*)smem;                  // MMA_M*KATOM
  float* Bs = As + MMA_M*KATOM;              // BN*KATOM
  const int As_addr = (int)__cvta_generic_to_shared(As);
  const int Bs_addr = (int)__cvta_generic_to_shared(Bs);

  #pragma nv_diag_suppress static_var_with_dynamic_init
  __shared__ unsigned long long mbar[1];
  __shared__ int tmem_addr[1];
  const int mbar_addr = (int)__cvta_generic_to_shared(mbar);

  if (warp_id == 0 && elect_one()) {
    mbar_init(mbar_addr, 1);
    asm volatile("fence.mbarrier_init.release.cluster;");
  } else if (warp_id == 1) {
    const int a = (int)__cvta_generic_to_shared(tmem_addr);
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" :: "r"(a), "r"(BN));
  }
  __syncthreads();
  const int taddr = tmem_addr[0];
  int phase = 0;

  // TF32 instruction descriptor.
  const unsigned i_desc = (1u<<4) | (2u<<7) | (2u<<10)
                        | (((unsigned)BN>>3)<<17) | (((unsigned)MMA_M>>4)<<24);
  auto desc = [&](int addr, int height) -> unsigned long long {
    unsigned long long LBO = (unsigned long long)height * 16ull;
    unsigned long long SBO = 8ull * 16ull;
    return enc((unsigned long long)addr) | (enc(LBO) << 16ull) | (enc(SBO) << 32ull) | (1ull << 46ull);
  };
  const unsigned long long ad = desc(As_addr, MMA_M);
  const unsigned long long bd = desc(Bs_addr, BN);

  const float* Vmat = Vb + (long)bid_mat * 32 * PH;
  const float* Amat = Ab + (long)bid_mat * PH * NC;

  const int nk = PH / KATOM;
  for (int ki = 0; ki < nk; ki++) {
    const int k0 = ki * KATOM;
    // A-operand tile = V[:, k0:k0+8] padded to M=64. smem [m][k].
    for (int idx = tid; idx < MMA_M*KATOM; idx += blockDim.x) {
      int m = idx / KATOM, kk = idx % KATOM;
      As[idx] = (m < 32) ? Vmat[(long)m*PH + (k0+kk)] : 0.0f;
    }
    // B-operand tile = A_trail[k0:k0+8, n0:n0+BN]. smem [n][k].
    for (int idx = tid; idx < BN*KATOM; idx += blockDim.x) {
      int nn = idx / KATOM, kk = idx % KATOM;
      int col = n0 + nn;
      Bs[idx] = (col < NC) ? Amat[(long)(k0+kk)*NC + col] : 0.0f;
    }
    __syncthreads();
    asm volatile("tcgen05.fence::after_thread_sync;");
    if (warp_id == 0 && elect_one()) {
      asm volatile(
        "{\n\t.reg .pred p;\n\tsetp.ne.b32 p, %4, 0;\n\t"
        "tcgen05.mma.cta_group::1.kind::tf32 [%0], %1, %2, %3, p;\n\t}"
        :: "r"(taddr), "l"(ad), "l"(bd), "r"(i_desc), "r"(ki));
      asm volatile("tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];" :: "r"(mbar_addr) : "memory");
    }
    mbar_wait(mbar_addr, phase);
    phase ^= 1;
    __syncthreads();
  }

  asm volatile("tcgen05.fence::after_thread_sync;");
  float* Wmat = Wb + (long)bid_mat * 32 * NC;
  if (warp_id == 0) {
    for (int n = 0; n < BN; n += 8) {
      float tmp[8];
      const int addr = taddr + ((warp_id*32)<<16) + n;
      asm volatile("tcgen05.ld.sync.aligned.32x32b.x8.b32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
          : "=f"(tmp[0]),"=f"(tmp[1]),"=f"(tmp[2]),"=f"(tmp[3]),"=f"(tmp[4]),"=f"(tmp[5]),"=f"(tmp[6]),"=f"(tmp[7])
          : "r"(addr));
      asm volatile("tcgen05.wait::ld.sync.aligned;");
      int row = lane;
      for (int c = 0; c < 8; c++) {
        int col = n0 + n + c;
        if (col < NC) Wmat[(long)row*NC + col] = tmp[c];
      }
    }
  }
  __syncthreads();
  if (warp_id == 0 && elect_one())
    asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" :: "r"(taddr), "r"(BN));
}
'''

def build():
    d = cd.cuCtxGetDevice()[1]
    maj = cd.cuDeviceGetAttribute(cd.CUdevice_attribute.CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR, d)[1]
    mn  = cd.cuDeviceGetAttribute(cd.CUdevice_attribute.CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR, d)[1]
    arch = f"--gpu-architecture=sm_{maj}{mn}a".encode()
    err, prog = nvrtc.nvrtcCreateProgram(TCG_SRC.encode(), b"w.cu", 0, [], [])
    (err,) = nvrtc.nvrtcCompileProgram(prog, 2, [arch, b"--std=c++17"])
    _, logsz = nvrtc.nvrtcGetProgramLogSize(prog)
    if logsz > 1:
        log = bytearray(logsz); nvrtc.nvrtcGetProgramLog(prog, log)
        s = log.decode(errors="replace").strip()
        if s: print("[NVRTC]", s, flush=True)
    assert err == nvrtc.nvrtcResult.NVRTC_SUCCESS, f"compile failed {err}"
    sz = nvrtc.nvrtcGetCUBINSize(prog)[1]
    cubin = bytearray(sz); nvrtc.nvrtcGetCUBIN(prog, cubin)
    m = cd.cuModuleLoadData(bytes(cubin))[1]
    f = cd.cuModuleGetFunction(m, b"w_tcgen05")[1]
    maxsmem = cd.cuDeviceGetAttribute(cd.CUdevice_attribute.CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN, d)[1]
    cd.cuFuncSetAttribute(f, cd.CUfunction_attribute.CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, maxsmem)
    return f

FUNC = build()
print("tcgen05 kernel compiled.", flush=True)
BN = 256
NTH = 128

def run_tcgen05(V, At, BN=BN):
    Bb, _, PHl = V.shape; NCl = At.shape[2]
    W = torch.zeros(Bb, 32, NCl, device=dev, dtype=torch.float32)
    smem = (64*8 + BN*8) * 4
    grid_n = (NCl + BN - 1) // BN
    a = [np.array([V.data_ptr()], dtype=np.uint64), np.array([At.data_ptr()], dtype=np.uint64),
         np.array([W.data_ptr()], dtype=np.uint64),
         np.array([Bb], dtype=np.int32), np.array([PHl], dtype=np.int32),
         np.array([NCl], dtype=np.int32), np.array([BN], dtype=np.int32)]
    argv = np.array([x.ctypes.data for x in a], dtype=np.uint64)
    cur = torch.cuda.current_stream()
    err, = cd.cuLaunchKernel(FUNC, grid_n, Bb, 1, NTH, 1, 1, smem,
                             cd.CUstream(cur.cuda_stream), argv.ctypes.data, 0)
    if err != cd.CUresult.CUDA_SUCCESS:
        raise RuntimeError(f"launch failed {err}")
    return W

# ---- Triton W-reduction (sweep-1 of _trailing_fused_kernel, NACC=2/NS=3 shape) ----
@triton.jit
def _w_triton(A_ptr, V_ptr, W_ptr, B, PH, NC,
              sab, san, svb, svk, svn, swb, swk, swn,
              BLK: tl.constexpr, BM: tl.constexpr, BNc: tl.constexpr, NS: tl.constexpr):
    col_tile = tl.program_id(0); bid = tl.program_id(1)
    if bid >= B: return
    c0 = col_tile * BNc
    ccols = c0 + tl.arange(0, BNc); cmask = ccols < NC
    krange = tl.arange(0, BLK)
    a_base = A_ptr + bid*sab; v_base = V_ptr + bid*svb
    nchunks = tl.cdiv(PH, BM)
    W0 = tl.zeros((BLK, BNc), dtype=tl.float32); W1 = tl.zeros((BLK, BNc), dtype=tl.float32)
    for ci in tl.range(0, nchunks, num_stages=NS):
        rr = ci*BM + tl.arange(0, BM); rrmask = rr < PH
        ap = a_base + rr[:, None]*san + ccols[None, :]
        achunk = tl.load(ap, mask=rrmask[:, None] & cmask[None, :], other=0.0)
        vp = v_base + krange[:, None]*svk + rr[None, :]*svn
        vchunk = tl.load(vp, mask=rrmask[None, :], other=0.0)
        d = tl.dot(vchunk, achunk, input_precision="tf32x3")
        if ci % 2 == 0: W0 += d
        else: W1 += d
    W = W0 + W1
    wp = W_ptr + bid*swb + krange[:, None]*swk + ccols[None, :]*swn
    tl.store(wp, W, mask=cmask[None, :])

def run_triton(V, At, BM=32, BNc=64, NS=3):
    Bb, _, PHl = V.shape; NCl = At.shape[2]
    W = torch.zeros(Bb, 32, NCl, device=dev, dtype=torch.float32)
    nct = triton.cdiv(NCl, BNc)
    _w_triton[(nct, Bb)](At, V, W, Bb, PHl, NCl,
                         At.stride(0), At.stride(1), V.stride(0), V.stride(1), V.stride(2),
                         W.stride(0), W.stride(1), W.stride(2),
                         BLK=32, BM=BM, BNc=BNc, NS=NS, num_warps=2)
    return W

def relerr(x, ref):
    return (x.double()-ref.double()).abs().max().item() / (ref.double().abs().max().item()+1e-30)

# ---- validate first (single launch each) ----
W_tcg = run_tcgen05(V, At); torch.cuda.synchronize()
W_tri = run_triton(V, At); torch.cuda.synchronize()
e_tcg = relerr(W_tcg, W_ref); e_tri = relerr(W_tri, W_ref)
print(f"VALIDATE  tcgen05 max-relerr={e_tcg:.2e}   triton max-relerr={e_tri:.2e}   (tf32 ~1e-3 ok)", flush=True)
tcg_ok = e_tcg < 5e-3
if not tcg_ok:
    print(f"KILL-GATE: tcgen05 NUMERICALLY WRONG (relerr {e_tcg:.2e}) -> descriptor/layout bug.", flush=True)
    sys.exit(0)

if MODE != "bench":
    print("validate-only mode done (tcgen05 correct). Re-run with 'bench' to time.", flush=True)
    sys.exit(0)

# ---- A/B timing, interleaved, util=0 ----
l2 = torch.empty(int(80e6 // 4), dtype=torch.float32, device=dev)
def bench_interleaved(fa, fb, reps=50, warmup=12):
    for _ in range(warmup): fa(); fb()
    torch.cuda.synchronize()
    ta, tb = [], []
    for _ in range(reps):
        for fn, acc in ((fa, ta), (fb, tb)):
            l2.zero_(); torch.cuda.synchronize()
            s = torch.cuda.Event(enable_timing=True); e = torch.cuda.Event(enable_timing=True)
            s.record(); fn(); e.record(); torch.cuda.synchronize()
            acc.append(s.elapsed_time(e)*1000.0)
    ta.sort(); tb.sort()
    return (ta[len(ta)//2], ta[0]), (tb[len(tb)//2], tb[0])

(tri_med, tri_min), (tcg_med, tcg_min) = bench_interleaved(
    lambda: run_triton(V, At), lambda: run_tcgen05(V, At))
print(f"TIMING (n=512 j=0 W-reduction, B=640, interleaved A/B, util=0):", flush=True)
print(f"  triton  W-reduction: median={tri_med:8.1f}us  min={tri_min:8.1f}us", flush=True)
print(f"  tcgen05 W-reduction: median={tcg_med:8.1f}us  min={tcg_min:8.1f}us", flush=True)
verdict = "WIN" if tcg_min < tri_min else "LOSE"
print(f"KILL-GATE: tcgen05 {'beats' if tcg_min<tri_min else 'does NOT beat'} triton -> {verdict}  (ratio {tri_min/tcg_min:.2f}x)", flush=True)

