l2 = torch.empty(int(80e6 // 4), dtype=torch.float32, device=dev)
def bench_interleaved(fa, fb, reps=50, warmup=12):
    for _ in range(warmup): fa(); fb()
    torch.cuda.synchronize()
    ta, tb = [], []
    for _ in range(reps):
