    return (ta[len(ta)//2], ta[0]), (tb[len(tb)//2], tb[0])

(tri_med, tri_min), (tcg_med, tcg_min) = bench_interleaved(
    lambda: run_triton(V, At), lambda: run_tcgen05(V, At))
