dev=torch.device("cuda")

M, N, K = 64, 8, 64   # K=64 -> 8 K-atoms, tests accumulation
# A operand (M x K), B operand (N x K) [both K-major]; D = A @ B^T conceptually:
# tcgen05 computes D[m][n] = sum_k A[m][k]*B[n][k]  (B is K-major as N x K)
torch.manual_seed(1)
A = torch.zeros(M, K, device=dev, dtype=torch.float32); A[:32] = torch.randn(32, K, device=dev)*0.5
